import heapq

def match(orders):
    trades = []
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    order_info = {}  # id -> {'side':..., 'price':..., 'qty':..., 'active':bool}
    seq_counter = 0

    def add_resting(oid, side, price, qty, seq):
        order_info[oid] = {'side': side, 'price': price, 'qty': qty, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = order_info.get(oid)
            if info and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        seq_counter += 1
        seq = seq_counter

        if typ == 'limit':
            _, oid, side, price, qty = order
            price_limit = price
        elif typ == 'ioc':
            _, oid, side, price, qty = order
            price_limit = price
        elif typ == 'market':
            _, oid, side, qty = order
            price_limit = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            heap = sell_heap
            while remaining > 0 and heap:
                p, s, other_id = heap[0]
                info = order_info.get(other_id)
                if not info or not info['active'] or info['qty'] <= 0:
                    heapq.heappop(heap)
                    continue
                if price_limit is not None and p > price_limit:
                    break
                trade_qty = min(remaining, info['qty'])
                trades.append([oid, other_id, p, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['active'] = False
                    heapq.heappop(heap)

            if typ == 'limit' and remaining > 0:
                add_resting(oid, side, price, remaining, seq)
            else:
                order_info[oid] = {'side': side, 'price': price_limit, 'qty': 0, 'active': False}
        else:
            heap = buy_heap
            while remaining > 0 and heap:
                negp, s, other_id = heap[0]
                p = -negp
                info = order_info.get(other_id)
                if not info or not info['active'] or info['qty'] <= 0:
                    heapq.heappop(heap)
                    continue
                if price_limit is not None and p < price_limit:
                    break
                trade_qty = min(remaining, info['qty'])
                trades.append([other_id, oid, p, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['active'] = False
                    heapq.heappop(heap)

            if typ == 'limit' and remaining > 0:
                add_resting(oid, side, price, remaining, seq)
            else:
                order_info[oid] = {'side': side, 'price': price_limit, 'qty': 0, 'active': False}

    return trades

